scripts.portfolio_value:
def solve(inputs: dict) -> float:
    quantities = inputs['QUANTITIES']
    prices = inputs['PRICES']
    total_value = sum(q * p for q, p in zip(quantities, prices))
    return float(total_value)

scripts.modular_power:
def solve(inputs: dict) -> float:
    base = inputs['BASE']
    exp = inputs['EXP']
    mod = inputs['MOD']
    result = pow(base, exp, mod)
    return float(result)

